  if (!u || vistas.has(u) || vistosCiclo.has(u)) continue;
  if (!fechaValida(j.fecha_publicacion)) continue;
  const s = ((j.titulo || '') + ' ' + (j.snippet || '')).toLowerCase();
  if (descartarPalabras.some(p => s.includes(p))) continue;
  vistosCiclo.add(u);
  salida.push({ json: { ...j, url_canonica: u } });
  if (salida.length >= maxHallazgos) break;
}
if (salida.length === 0) {
  return [{ json: { _resumen: 'sin candidatos nuevos', _fallidas: fallidas.join(', ') || 'ninguna' } }];
}
return salida;

